# check $ObjectSchema (.'$ObjectSchema')
sub json_model_7($$$)
{
    my ($val, $path, $rep) = @_;
    # .'$ObjectSchema'
    unless (jm_is_object($val))
    {
        push @$rep, ["not an object [.'\$ObjectSchema']", $path] if defined $rep;
        return 0;
    }
    my $pfun;
    scalar keys %$val;
    for my $prop (sort keys %$val)
    {
        my $pval = $$val{$prop};
        my $lpath_0 = defined $path ? [@{$path}, $prop] : undef;
        if (($pfun = $json_model_7_map{$prop}))
        {
            # handle 57 may props
            if (defined($pfun) && ! &$pfun($pval, defined $path ? $lpath_0 : undef, $rep))
            {
                push @$rep, ["invalid optional prop value [.'\$ObjectSchema']", defined $path ? $lpath_0 : undef] if defined $rep;
                return 0;
            }
            next;
        }
        push @$rep, ["unexpected prop [.'\$ObjectSchema']", defined $path ? $lpath_0 : undef] if defined $rep;
        return 0;
    }
    return 1;
}

# check $Schema (.'$Schema')
sub json_model_8($$$)
{
    my ($val, $path, $rep) = @_;
    # .'$Schema'
    # .'$Schema'.'|'.0
    my $res = jm_is_boolean($val);
    unless ($res)
    {
        push @$rep, ["not a bool [.'\$Schema'.'|'.0]", $path] if defined $rep;
        # .'$Schema'.'|'.1
        $res = json_model_7($val, $path, $rep);
        push @$rep, ["unexpected value for model \"\$ObjectSchema\" [.'\$Schema'.'|'.1]", $path] if defined $rep and not $res;
    }
    if ($res)
    {
        @$rep = () if defined $rep;
    }
    else
    {
        push @$rep, ["no model matched [.'\$Schema'.'|']", $path] if defined $rep;
    }
    return $res;
}

# check $stringArray (.'$stringArray')
sub json_model_9($$$)
{
    my ($val, $path, $rep) = @_;
    # .'$stringArray'
    # .'$stringArray'.'@'
    my $res = jm_is_array($val);
    if ($res)
    {
        for my $arr_2_idx (0 .. $#$val)
        {
            my $arr_2_item = $$val[$arr_2_idx];
            my $arr_2_lpath = defined $path ? [@{$path}, $arr_2_idx] : undef;
            # .'$stringArray'.'@'.0
            $res = jm_is_string($arr_2_item);
            unless ($res)
            {
                push @$rep, ["unexpected value for model \"\" [.'\$stringArray'.'\@'.0]", defined $path ? $arr_2_lpath : undef] if defined $rep;
                last;
            }
        }
    }
    if ($res)
    {
        $res = jm_is_unique_array($val, $path, $rep);
        push @$rep, ["constraints failed [.'\$stringArray']", $path] if defined $rep and not $res;
    }
    else
    {
        push @$rep, ["not array or unexpected array [.'\$stringArray'.'\@']", $path] if defined $rep;
    }
    return $res;
}

# check $ (.)
sub json_model_1($$$)
{
    my ($val, $path, $rep) = @_;
    # .
    my $res = json_model_8($val, $path, $rep);
    push @$rep, ["unexpected value for model \"\$Schema\" [.]", $path] if defined $rep and not $res;
    return $res;
}


